<template>
  <div><PageHeader eyebrow="ADMIN · IDENTITY" title="Vai trò & Quyền" description="Role catalog được quản lý trong tenant, chỉ cấp các permission caller đang sở hữu."><template #actions><button class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Tạo role' }}</button></template></PageHeader><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><section v-if="showForm" class="panel" style="margin-bottom:16px"><form class="inline-form" @submit.prevent="create"><div class="form-field"><label>Tên role</label><input v-model.trim="form.name" class="form-input" required placeholder="CONTENT_EDITOR" /></div><div class="form-field"><label>Permissions (phân tách bằng dấu phẩy)</label><input v-model.trim="form.permissions" class="form-input" placeholder="academics.courses.read" /></div><button class="button primary" :disabled="busy">Tạo role</button></form></section><section class="panel"><div class="panel-heading"><h2>Role catalog</h2><span>{{ roles.length }} role</span></div><div v-if="loading" class="loading-state">Đang tải role…</div><div v-else-if="roles.length" class="list-compact"><div v-for="role in roles" :key="role.id" class="list-compact-item"><div><strong>{{ role.name }}</strong><span>{{ role.permissions.join(' · ') || 'Chưa cấp permission' }}</span></div><button class="mini-button" @click="remove(role)">Xóa</button></div></div><div v-else class="empty-state"><strong>Chưa có role</strong><span>Role built-in sẽ có sau bootstrap.</span></div></section></div>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import { identityApi } from '../../../shared/api/client'; const roles = ref<{ id: string; name: string; permissions: string[] }[]>([]); const loading = ref(true); const busy = ref(false); const showForm = ref(false); const error = ref(''); const form = reactive({ name: '', permissions: '' }); async function load() { loading.value = true; try { roles.value = await identityApi.roles() } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được role.') } finally { loading.value = false } }; async function create() { busy.value = true; try { const role = await identityApi.createRole({ name: form.name, permissions: form.permissions.split(',').map(item => item.trim()).filter(Boolean) }); roles.value.push(role); form.name = ''; form.permissions = ''; showForm.value = false } catch (cause) { error.value = String((cause as Error)?.message || 'Không tạo được role.') } finally { busy.value = false } }; async function remove(role: { id: string; name: string }) { if (!window.confirm(`Xóa role ${role.name}?`)) return; try { await identityApi.deleteRole(role.id); roles.value = roles.value.filter(item => item.id !== role.id) } catch (cause) { error.value = String((cause as Error)?.message || 'Không xóa được role.') } }; onMounted(load)
</script>
